server.tool(
  'get_board_state',
  'Get the current board state, legal moves, and game status.',
  { room_id: z.number().describe('Room ID') },
  async ({ room_id }) => {
    try {
      const { token } = requireAuth();
      const state = await client.getRoomState(token, room_id);
      return ok(state);
    } catch (err) {
      return errorResponse(err);
    }
  }
);

