8	    this.roomId = roomId;
9	    this.token = token;
10	    this.state = 'connecting'; // connecting | connected | reconnecting | closed
11	    this.eventBuffer = [];
12	    this.waiters = [];
13	    this.retryCount = 0;
14	    this.maxRetries = 5;
15	    this.ws = null;
16	    this._readyResolve = null;
17	    this.readyPromise = new Promise((resolve) => { this._readyResolve = resolve; });
18	    this._connect();
