48	      }
49	    });
50	
51	    this.ws.on('error', () => {
52	      // close event always follows — reconnection handled there
53	    });
54	
55	    this.ws.on('close', () => {
56	      if (this.state === 'closed') return;
57	      this.state = 'reconnecting';
58	      this._reconnect();
59	    });
60	  }
61	
62	  _reconnect() {
63	    if (this.state === 'closed') return;
64	    if (this.retryCount >= this.maxRetries) {
65	      this._fail(new Error('Max reconnection attempts exceeded'));
66	      return;
67	    }
68	    const delay = Math.min(1000 * 2 ** this.retryCount, 30000);
69	    this.retryCount++;
70	    this.readyPromise = new Promise((resolve) => { this._readyResolve = resolve; });
71	    setTimeout(() => {
72	      if (this.state === 'closed') return;
73	      this._connect();
74	    }, delay);
75	  }
