93	    if (this.state === 'closed') {
94	      return Promise.reject(new Error('Connection closed'));
95	    }
96	
97	    // Check buffer first
98	    const idx = this.eventBuffer.findIndex((msg) => eventNames.includes(msg.event));
99	    if (idx >= 0) {
100	      return Promise.resolve(this.eventBuffer.splice(idx, 1)[0]);
101	    }
102	
103	    return new Promise((resolve, reject) => {
104	      const timer = setTimeout(() => {
105	        const i = this.waiters.findIndex((w) => w.timer === timer);
106	        if (i >= 0) this.waiters.splice(i, 1);
107	        reject(new Error(`Timed out waiting for events: ${eventNames.join(', ')}`));
108	      }, timeoutMs);
109	      this.waiters.push({ eventNames, resolve, reject, timer });
110	    });
111	  }
