114	    if (this.state === 'closed') return;
115	    this.state = 'closed';
116	    for (const waiter of this.waiters) {
117	      clearTimeout(waiter.timer);
118	      waiter.reject(new Error('Connection closed'));
119	    }
120	    this.waiters = [];
121	    this.eventBuffer = [];
122	    if (this.ws) {
123	      this.ws.removeAllListeners();
124	      this.ws.close(1000);
125	    }
126	  }
